mapper.select:
SELECT r.id, r.target_type AS targetType, reporter.name AS reporterName, target_member.name AS targetUserName, p.content AS content, r.reason, r.created_at AS createdAt, r.status
FROM report r JOIN member reporter ON reporter.id = r.member_id LEFT JOIN post p ON p.id = r.post_id LEFT JOIN member target_member ON target_member.id = p.member_id WHERE 1 = 1
AND r.target_type = #{targetType}
AND r.status = #{status}
ORDER BY r.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT r.id, r.target_type AS targetType, reporter.name AS reporterName, target_member.name AS targetUserName, p.content AS content, r.reason, r.content AS reportContent, r.created_at AS createdAt, r.status
FROM report r JOIN member reporter ON reporter.id = r.member_id LEFT JOIN post p ON p.id = r.post_id LEFT JOIN member target_member ON target_member.id = p.member_id
WHERE r.id = #{reportId}
